569	// Handshake attaches: it sends the identity and gets the state of the runtime back, or an
570	// IncompatibleError naming each field that differs.
571	func (c Client) Handshake(ctx context.Context) (Reply, error) {
572		id := c.Identity
573		reply, err := c.roundTrip(ctx, Request{Op: "handshake", Identity: &id})
574		if err != nil {
575			return Reply{}, err
576		}
577		if len(reply.Mismatch) > 0 {
578			sort.Strings(reply.Mismatch)
579			return reply, &IncompatibleError{Mismatch: reply.Mismatch}
580		}
581		if !reply.OK {
582			return reply, errors.New(reply.Error)
583		}
584		return reply, nil
585	}
