11	// runtimeAdmission is the runtime's policy for hosted commands: two lanes, each with its own
12	// slots and queue, so that a short query is never queued behind a heavy check, and a bound on
13	// what waits. The defaults are the ones the measurements of the spec were made with.
14	type runtimeAdmission struct {
15		HeavySlots, ShortSlots int
16		HeavyQueue, ShortQueue int
17		MemoMiB                int
18	}
19	
20	func defaultRuntimeAdmission() runtimeAdmission {
21		heavy := 1
22		short := 2
23		if runtime.GOMAXPROCS(0) < 2 {
24			short = 1
25		}
26		return runtimeAdmission{HeavySlots: heavy, ShortSlots: short, HeavyQueue: 4, ShortQueue: 16, MemoMiB: 256}
27	}
28	
29	// shortCommands are the hosted commands that answer in well under a second on a repository of
30	// this size (measured in the spec: surface-check of one spec takes about 10 ms; roadmap-check
31	// takes minutes here); every other hosted command is heavy.
32	var shortCommands = map[string]bool{"surface-check": true}
