34	// hostedLane is one lane of the admission policy and its counters.
35	type hostedLane struct {
36		name     string
37		slots    chan struct{}
38		maxQueue int64
39		queued   atomic.Int64
40		running  atomic.Int64
41		admitted atomic.Int64
42		refused  atomic.Int64
43		waitNS   atomic.Int64
44		maxWait  atomic.Int64
45	}
46	
47	func newHostedLane(name string, slots, queue int) *hostedLane {
48		if slots < 1 {
49			slots = 1
50		}
51		return &hostedLane{name: name, slots: make(chan struct{}, slots), maxQueue: int64(queue)}
52	}
53	
54	// enter reserves a place in the queue; false means every slot is busy and the queue is full,
55	// and the command is refused before it waits. Two arrivals that find the same last free slot
56	// may both wait: the queue limit can be exceeded by the arrivals of one instant.
57	func (l *hostedLane) enter() bool {
58		if l.queued.Add(1) > l.maxQueue && len(l.slots) == cap(l.slots) {
59			l.queued.Add(-1)
60			l.refused.Add(1)
61			return false
62		}
63		return true
64	}
65	
66	func (l *hostedLane) admit(wait time.Duration) {
67		l.queued.Add(-1)
68		l.running.Add(1)
69		l.admitted.Add(1)
70		l.waitNS.Add(int64(wait))
71		for {
72			cur := l.maxWait.Load()
73			if int64(wait) <= cur || l.maxWait.CompareAndSwap(cur, int64(wait)) {
74				return
75			}
76		}
77	}
78	
79	func (l *hostedLane) withdrawn() { l.queued.Add(-1); l.refused.Add(1) }
80	
81	func (l *hostedLane) metrics(out map[string]int64) {
82		out[l.name+"_slots"] = int64(cap(l.slots))
83		out[l.name+"_queue_limit"] = l.maxQueue
84		out[l.name+"_queued"] = l.queued.Load()
85		out[l.name+"_running"] = l.running.Load()
86		out[l.name+"_admitted"] = l.admitted.Load()
87		out[l.name+"_refused"] = l.refused.Load()
88		out[l.name+"_wait_ms_total"] = l.waitNS.Load() / int64(time.Millisecond)
89		out[l.name+"_wait_ms_max"] = l.maxWait.Load() / int64(time.Millisecond)
90	}
