92	type hostedLanes struct{ heavy, short *hostedLane }
93	
94	func newHostedLanes(p runtimeAdmission) *hostedLanes {
95		return &hostedLanes{heavy: newHostedLane("heavy", p.HeavySlots, p.HeavyQueue), short: newHostedLane("short", p.ShortSlots, p.ShortQueue)}
96	}
